tool_args.command:
source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && for f in /root/entrainment_gated_ft/lm_eval_clean/*.json; do echo "=== $(basename $f) ==="; python3 -c "
import json
d=json.load(open('$f'))
if 'results' in d and isinstance(d['results'], dict):
    for k,v in d['results'].items():
        if isinstance(v, dict):
            acc = v.get('acc,none', v.get('acc_norm,none', 'N/A'))
            print(f'  {k}: acc={acc}')
        else:
            print(f'  {k}: {v}')
elif isinstance(d, dict):
    for k in list(d.keys())[:5]:
        print(f'  {k}')
" 2>/dev/null; done
